CREATE TABLE roadmaps (id UUID PRIMARY KEY, project_id UUID NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE roadmap_phases (id UUID PRIMARY KEY, roadmap_id UUID NOT NULL REFERENCES roadmaps(id) ON DELETE CASCADE, position INTEGER NOT NULL, title VARCHAR(160) NOT NULL, description TEXT, status VARCHAR(30) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(roadmap_id, position));
CREATE TABLE tasks (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, phase_id UUID NOT NULL REFERENCES roadmap_phases(id) ON DELETE CASCADE, position INTEGER NOT NULL, title VARCHAR(200) NOT NULL, objective TEXT NOT NULL, status VARCHAR(30) NOT NULL, risk_level VARCHAR(20) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, started_at TIMESTAMP WITH TIME ZONE, completed_at TIMESTAMP WITH TIME ZONE, UNIQUE(phase_id, position));
CREATE TABLE task_dependencies (task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, dependency_task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE RESTRICT, PRIMARY KEY(task_id, dependency_task_id), CHECK(task_id <> dependency_task_id));
CREATE TABLE task_acceptance_criteria (id UUID PRIMARY KEY, task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, description TEXT NOT NULL, required BOOLEAN NOT NULL, status VARCHAR(20) NOT NULL);
CREATE TABLE task_evidence (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, type VARCHAR(30) NOT NULL, raw_content TEXT NOT NULL, source VARCHAR(80) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE output_analysis_records (id UUID PRIMARY KEY, evidence_id UUID NOT NULL UNIQUE REFERENCES task_evidence(id) ON DELETE CASCADE, status VARCHAR(30) NOT NULL, summary TEXT NOT NULL, signals TEXT NOT NULL, should_continue BOOLEAN NOT NULL, requires_correction BOOLEAN NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
